SELECT * FROM (SELECT CASE WHEN amount >= 1470 THEN 'high' WHEN amount >= 770 THEN 'mid' ELSE 'low' END AS amount_bucket, SUM(CASE WHEN status = 'PENDING' THEN 1 ELSE 0 END) AS pending_count, CONCAT_WS(', ', SORT_ARRAY(COLLECT_SET(status))) AS status_values FROM orders WHERE channel IN ('partner', 'web') GROUP BY CASE WHEN amount >= 1470 THEN 'high' WHEN amount >= 770 THEN 'mid' ELSE 'low' END) AS sub WHERE pending_count > 22;
